document.addEventListener('DOMContentLoaded', function () {
    const workItems = document.querySelectorAll('.work, .services-frame-item, .project-wrap .item, .our-services-frame .item');
    const loadedVideos = new Map();
    const preloadTime = 2; // сколько секунд проигрывать при предзагрузке

    function safePlay(video) {
        return new Promise(resolve => {
            if (video.readyState >= 3) {
                video.play().then(resolve).catch(resolve);
            } else {
                video.addEventListener("canplaythrough", () => video.play().then(resolve).catch(resolve), { once: true });
            }
        });
    }

    function handleVideoReady(video, image, parent) {
        const isSpecialParent = parent.closest('.services-frame-item, .our-services-frame');
        if (isSpecialParent) {
            video.style.display = 'flex';
            if (image) image.style.display = 'none';
        } else {
            video.style.opacity = '1';
            if (image) image.style.opacity = '0';
        }
    }

    function handleVideoNotReady(video, image, parent) {
        const isSpecialParent = parent.closest('.services-frame-item, .our-services-frame');
        if (isSpecialParent) {
            video.style.display = 'none';
            if (image) image.style.display = 'block';
        } else {
            video.style.opacity = '0';
            if (image) image.style.opacity = '1';
        }
    }

    function initVideosForItem(item) {
        const videos = item.querySelectorAll('.preview-video, .services-video');
        if (!videos.length) return;

        let activeVideo = null;
        let videoReadyCheckers = new Map();

        videos.forEach(video => {
            const source = video.querySelector('source');
            const src = source?.dataset.src;

            const parentBlock = video.closest('.work, .services-frame-item, .item, .project-wrap, .our-services-frame');
            const image = parentBlock ? parentBlock.querySelector('img') : null;
            const isSpecialParent = parentBlock.closest('.services-frame-item, .our-services-frame');

            if (isSpecialParent) {
                video.style.display = 'none';
                if (image) {
                    image.style.display = 'block';
                    image.style.opacity = '1';
                    image.style.transition = 'opacity 0.3s ease';
                }
            } else {
                video.style.opacity = '0';
                video.style.transition = 'opacity 0.3s ease';
                if (image) {
                    image.style.opacity = '1';
                    image.style.transition = 'opacity 0.3s ease';
                }
            }

            if (isDesktop && src && !video.src) {
                video.src = src;
                loadedVideos.set(src, video);
                video.load();

                // Предзагрузка: проигрываем 2-3 секунды и ставим на паузу
                video.muted = true;
                video.currentTime = 0;
                safePlay(video).then(() => {
                    setTimeout(() => {
                        video.pause();
                        video.currentTime = 0;
                    }, preloadTime * 1000);
                });
            }

            video.pause();
            video.currentTime = 0;

            if (isDesktop) video.classList.remove('show-video');
        });

        if (isDesktop) {
            const playVideo = (video) => {
                if (activeVideo && activeVideo !== video) pauseVideo(activeVideo);

                const parentBlock = video.closest('.work, .services-frame-item, .item, .project-wrap, .our-services-frame');
                const image = parentBlock ? parentBlock.querySelector('img') : null;

                if (video.readyState >= 3) {
                    video.muted = true;
                    safePlay(video);
                    video.classList.add('show-video');
                    handleVideoReady(video, image, parentBlock);
                    item.setAttribute('data-video-playing', 'true');
                    activeVideo = video;
                } else {
                    handleVideoNotReady(video, image, parentBlock);
                    const onCanPlay = () => {
                        video.muted = true;
                        safePlay(video);
                        video.classList.add('show-video');
                        handleVideoReady(video, image, parentBlock);
                        item.setAttribute('data-video-playing', 'true');
                        activeVideo = video;
                    };

                    const existingChecker = videoReadyCheckers.get(video);
                    if (existingChecker) video.removeEventListener('canplay', existingChecker);
                    video.addEventListener('canplay', onCanPlay, { once: true });
                    videoReadyCheckers.set(video, onCanPlay);
                }
            };

            const pauseVideo = (video) => {
                if (!video) return;

                const parentBlock = video.closest('.work, .services-frame-item, .item, .project-wrap, .our-services-frame');
                const image = parentBlock ? parentBlock.querySelector('img') : null;

                video.pause();
                video.currentTime = 0;
                video.classList.remove('show-video');

                const isSpecialParent = parentBlock.closest('.services-frame-item, .our-services-frame');
                if (isSpecialParent) {
                    video.style.display = 'none';
                    if (image) {
                        image.style.display = 'block';
                        image.style.opacity = '1';
                    }
                } else {
                    video.style.opacity = '0';
                    if (image) image.style.opacity = '1';
                }

                item.setAttribute('data-video-playing', 'false');

                const waitingHandler = videoReadyCheckers.get(video);
                if (waitingHandler) {
                    video.removeEventListener('canplay', waitingHandler);
                    videoReadyCheckers.delete(video);
                }

                if (activeVideo === video) activeVideo = null;
            };

            item.addEventListener('mouseenter', () => {
                const current = item.querySelector('.show-video') || videos[0];
                playVideo(current);
            });

            item.addEventListener('mouseleave', () => {
                if (activeVideo) pauseVideo(activeVideo);
            });
        }
    }

    workItems.forEach(initVideosForItem);
});


















// Preloader
let isPriorityVideoLoaded = false;
let isPageReady = false;

if (document.querySelector('.preloader')) {
    function isMobileDevice() {
        return /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
    }

    function tryStartAnimation() {
        if (isPriorityVideoLoaded && isPageReady) {
            runPreloaderAnimation();
        }
    }

    function checkPreloaderLoad() {
        const priorityVideo = document.querySelector('.showreel__body-video');

        let timeoutReached = false;

        const forceStart = () => {
            if (!timeoutReached) return;
            isPriorityVideoLoaded = true;
            tryStartAnimation();
        };

        setTimeout(() => {
            timeoutReached = true;
            if (!isPriorityVideoLoaded) {
                console.warn('Timeout reached → продолжаем без видео');
                forceStart();
            }
        }, 7000);

        if (priorityVideo) {
            if (priorityVideo.readyState >= 4) {
                isPriorityVideoLoaded = true;
                tryStartAnimation();
            } else {
                try { priorityVideo.load(); } catch (e) { }
                const videoHandler = () => {
                    isPriorityVideoLoaded = true;
                    tryStartAnimation();
                    priorityVideo.removeEventListener('canplaythrough', videoHandler);
                    priorityVideo.removeEventListener('error', videoHandler);
                };
                priorityVideo.addEventListener('canplaythrough', videoHandler);
                priorityVideo.addEventListener('error', videoHandler);

                if (isMobileDevice() && priorityVideo.readyState === 0) {
                    setTimeout(() => {
                        if (!isPriorityVideoLoaded) {
                            console.warn('iOS video load issue → запускаем без него');
                            isPriorityVideoLoaded = true;
                            tryStartAnimation();
                        }
                    }, 4000);
                }
            }
        } else {
            // если видео нет — запускаем сразу
            isPriorityVideoLoaded = true;
            tryStartAnimation();
        }
    }

    // Ждём полной загрузки страницы (DOM + ресурсы)
    window.addEventListener("load", () => {
        isPageReady = true;
        tryStartAnimation();
    });

    let widthText = isDesktop ? 600 : 300;

    function runPreloaderAnimation() {
        const tl = gsap.timeline({ defaults: { ease: "power2.inOut" } });
        tl.to('.last-text', {
            clipPath: 'inset(0 0% 0 0)',
            duration: 1,
            ease: 'power1'
        })
        tl.to(".preloader", {
            opacity: 0,
            duration: 0.8,
            delay: 0.5,
            onComplete: () => document.querySelector(".preloader").style.display = "none"
        });
    }

    checkPreloaderLoad();
}


