document.addEventListener("DOMContentLoaded", () => {
    const lazyImages = document.querySelectorAll("img[data-src]");

    const imageObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const img = entry.target;
                const src = img.dataset.src;

                if (src) {
                    img.src = src;
                    img.removeAttribute("data-src");
                }

                observer.unobserve(img);
            }
        });
    }, {
        rootMargin: "400px 0px",
        threshold: 0
    });

    lazyImages.forEach(img => imageObserver.observe(img));
});




const tippyInstances = [];
$('.feedback-form-inputs input').each(function (e) {
    const inputName = $(this).attr('name');
    const tippyElement = this
    const Text = $(this).attr('data-tippy')
    const instance = tippy(tippyElement, {
        content: `${Text}`,
        placement: 'top',
        animation: 'fade',
        arrow: true,
        name: inputName,
        theme: 'custom',
        trigger: 'manual',
    });
    tippyInstances.push(instance);
})
$('.form-action-send').on('click', function (e) {
    let col = 0;
    let formData = {};
    $('.feedback-form-inputs input').each(function () {
        const nameInput = $(this).attr('name')
        if ($(this).val() == '') {
            $(this).addClass('error');
            tippyInstances.forEach((item) => {
                if (item.props.name == nameInput) {
                    item.show()
                }
            })
        } else {
            $(this).removeClass('error');
            tippyInstances.forEach((item) => {
                if (item.props.name == nameInput) {
                    item.hide()
                }
            })
            col++;
            const name = $(this).attr('name');
            formData[name] = $(this).val();
        }
    });
});


